                        all(patch(name,read(p/('original.'+str(i))))==read(t) for i,(name,t) in enumerate(zip(FILES,paths)))):return True
            except (OSError,ValueError,KeyError):pass
    except (OSError,ValueError,ET.ParseError):pass
    return False

